CREATE TABLE IF NOT EXISTS public.discharge_workflows ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), hospital_id UUID NOT NULL REFERENCES hospitals(id) ON DELETE RESTRICT, admission_id UUID NOT NULL, patient_id UUID NOT NULL REFERENCES patients(id) ON DELETE RESTRICT, initiated_by UUID NOT NULL REFERENCES profiles(id) ON DELETE RESTRICT, status TEXT NOT NULL DEFAULT 'pending_review' CHECK (status IN ( 'pending_review', 'clinical_cleared', 'nurse_confirmed', 'med_reconciled', 'financial_cleared', 'discharged', 'finalized', 'cancelled' )), current_step INTEGER NOT NULL DEFAULT 1, cancellation_reason TEXT, clinical_notes JSONB DEFAULT '{}', medication_reconciliation JSONB DEFAULT '{}', financial_details JSONB DEFAULT '{}', checkout_details JSONB DEFAULT '{}', doctor_clearance_by UUID REFERENCES profiles(id) ON DELETE SET NULL, doctor_clearance_at TIMESTAMPTZ, nurse_confirmed_by UUID REFERENCES profiles(id) ON DELETE SET NULL, nurse_confirmed_at TIMESTAMPTZ, pharmacist_reconciliation_by UUID REFERENCES profiles(id) ON DELETE SET NULL, pharmacist_reconciliation_at TIMESTAMPTZ, billing_clearance_by UUID REFERENCES profiles(id) ON DELETE SET NULL, billing_clearance_at TIMESTAMPTZ, receptionist_checkout_by UUID REFERENCES profiles(id) ON DELETE SET NULL, receptionist_checkout_at TIMESTAMPTZ, metadata JSONB DEFAULT '{}', created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now() ); CREATE INDEX IF NOT EXISTS idx_discharge_workflows_admission ON discharge_workflows(admission_id); CREATE INDEX IF NOT EXISTS idx_discharge_workflows_hospital ON discharge_workflows(hospital_id); CREATE INDEX IF NOT EXISTS idx_discharge_workflows_patient ON discharge_workflows(patient_id); CREATE INDEX IF NOT EXISTS idx_discharge_workflows_status ON discharge_workflows(status); CREATE INDEX IF NOT EXISTS idx_discharge_workflows_created ON discharge_workflows(created_at DESC); CREATE TABLE IF NOT EXISTS public.discharge_workflow_tasks ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), hospital_id UUID NOT NULL REFERENCES hospitals(id) ON DELETE RESTRICT, discharge_workflow_id UUID NOT NULL REFERENCES discharge_workflows(id) ON DELETE CASCADE, task_name TEXT NOT NULL, task_category TEXT NOT NULL CHECK (task_category IN ( 'clinical', 'medication', 'financial', 'checkout' )), step_number INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ( 'pending', 'completed', 'skipped', 'not_applicable' )), assigned_to UUID REFERENCES profiles(id) ON DELETE SET NULL, completed_by UUID REFERENCES profiles(id) ON DELETE SET NULL, completed_at TIMESTAMPTZ, notes TEXT, evidence_data JSONB DEFAULT '{}', created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now() ); CREATE INDEX IF NOT EXISTS idx_discharge_workflow_tasks_workflow ON discharge_workflow_tasks(discharge_workflow_id); CREATE INDEX IF NOT EXISTS idx_discharge_workflow_tasks_status ON discharge_workflow_tasks(status); CREATE INDEX IF NOT EXISTS idx_discharge_workflow_tasks_hospital ON discharge_workflow_tasks(hospital_id); ALTER TABLE public.discharge_workflows ENABLE ROW LEVEL SECURITY; ALTER TABLE public.discharge_workflow_tasks ENABLE ROW LEVEL SECURITY; DROP POLICY IF EXISTS "discharge_workflows_hospital_scope" ON public.discharge_workflows; CREATE POLICY "discharge_workflows_hospital_scope" ON public.discharge_workflows FOR SELECT USING ( hospital_id = ( SELECT hospital_id FROM profiles WHERE id = auth.uid() ) ); DROP POLICY IF EXISTS "discharge_workflows_update_own_hospital" ON public.discharge_workflows; CREATE POLICY "discharge_workflows_update_own_hospital" ON public.discharge_workflows FOR UPDATE USING ( hospital_id = (SELECT hospital_id FROM profiles WHERE id = auth.uid()) ); DROP POLICY IF EXISTS "discharge_workflows_delete_admin_only" ON public.discharge_workflows; CREATE POLICY "discharge_workflows_delete_admin_only" ON public.discharge_workflows FOR DELETE USING ( auth.uid() IN ( SELECT user_id FROM user_roles WHERE role = 'admin' AND hospital_id = discharge_workflows.hospital_id ) ); DROP POLICY IF EXISTS "discharge_workflow_tasks_hospital_scope" ON public.discharge_workflow_tasks; CREATE POLICY "discharge_workflow_tasks_hospital_scope" ON public.discharge_workflow_tasks FOR SELECT USING ( hospital_id = ( SELECT hospital_id FROM profiles WHERE id = auth.uid() ) ); DROP POLICY IF EXISTS "discharge_workflow_tasks_update_own_hospital" ON public.discharge_workflow_tasks; CREATE POLICY "discharge_workflow_tasks_update_own_hospital" ON public.discharge_workflow_tasks FOR UPDATE USING ( hospital_id = (SELECT hospital_id FROM profiles WHERE id = auth.uid()) ); GRANT SELECT, INSERT, UPDATE, DELETE ON public.discharge_workflows TO authenticated; GRANT SELECT, INSERT, UPDATE, DELETE ON public.discharge_workflow_tasks TO authenticated; GRANT ALL ON public.discharge_workflows TO service_role; GRANT ALL ON public.discharge_workflow_tasks TO service_role; DROP TRIGGER IF EXISTS discharge_workflows_update_timestamp ON public.discharge_workflows; CREATE TRIGGER discharge_workflows_update_timestamp BEFORE UPDATE ON discharge_workflows FOR EACH ROW EXECUTE FUNCTION public.touch_row_updated_at(); DROP TRIGGER IF EXISTS discharge_workflow_tasks_update_timestamp ON public.discharge_workflow_tasks; CREATE TRIGGER discharge_workflow_tasks_update_timestamp BEFORE UPDATE ON discharge_workflow_tasks FOR EACH ROW EXECUTE FUNCTION public.touch_row_updated_at(); CREATE OR REPLACE FUNCTION public.log_discharge_workflow_status_change() RETURNS TRIGGER AS $fn$ BEGIN IF OLD.status IS DISTINCT FROM NEW.status THEN INSERT INTO audit_logs ( action_type, resource_type, resource_id, performed_by, hospital_id, details ) VALUES ( 'discharge_workflow_' || NEW.status, 'discharge_workflow', NEW.id, COALESCE( NEW.doctor_clearance_by, NEW.nurse_confirmed_by, NEW.pharmacist_reconciliation_by, NEW.billing_clearance_by, NEW.receptionist_checkout_by, auth.uid() ), NEW.hospital_id, jsonb_build_object('admission_id', NEW.admission_id, 'patient_id', NEW.patient_id, 'previous_status', OLD.status, 'new_status', NEW.status, 'current_step', NEW.current_step, 'cancellation_reason', NEW.cancellation_reason) ); END IF; RETURN NEW; END; $fn$ LANGUAGE plpgsql; CREATE OR REPLACE FUNCTION public.log_discharge_workflow_task_completion() RETURNS TRIGGER AS $fn$ BEGIN IF OLD.status IS DISTINCT FROM NEW.status THEN INSERT INTO audit_logs ( action_type, resource_type, resource_id, performed_by, hospital_id, details ) VALUES ( 'discharge_workflow_task_' || NEW.status, 'discharge_workflow_task', NEW.id, COALESCE(NEW.completed_by, auth.uid()), NEW.hospital_id, jsonb_build_object('discharge_workflow_id', NEW.discharge_workflow_id, 'task_name', NEW.task_name, 'task_category', NEW.task_category, 'previous_status', OLD.status, 'new_status', NEW.status, 'notes', NEW.notes) ); END IF; RETURN NEW; END; $fn$ LANGUAGE plpgsql; DROP TRIGGER IF EXISTS discharge_workflows_audit_status_change ON public.discharge_workflows; CREATE TRIGGER discharge_workflows_audit_status_change AFTER UPDATE ON discharge_workflows FOR EACH ROW EXECUTE FUNCTION log_discharge_workflow_status_change(); DROP TRIGGER IF EXISTS discharge_workflow_tasks_audit_status_change ON public.discharge_workflow_tasks; CREATE TRIGGER discharge_workflow_tasks_audit_status_change AFTER UPDATE ON discharge_workflow_tasks FOR EACH ROW EXECUTE FUNCTION log_discharge_workflow_task_completion(); COMMENT ON TABLE discharge_workflows IS 'Multi-role discharge workflow state machine. Tracks patient discharge from initiation through checkout.'; COMMENT ON COLUMN discharge_workflows.status IS 'Current state of discharge workflow: pending_review -> clinical_cleared -> nurse_confirmed -> med_reconciled -> financial_cleared -> discharged -> finalized (or cancelled at any point)';